text:
&.hub-form-grid {
  gap: 18px;
  --hub-width: 530px;
  display: grid;
  grid-template: repeat(3, auto 1fr) auto / repeat(4, 1fr);

  &.advanced {
    grid-template-rows: repeat(4, auto 1fr);
  }

  .stacked & {
    grid-template: repeat(6, auto 1fr) auto / repeat(2, 1fr);

    &.advanced {
      grid-template-rows: repeat(11, auto 1fr);
    }
  }

  & .input-cell {
    display: grid;
    grid-template-rows: subgrid;
    grid-row: span 2;
    gap: 3px;

    &.select-row {
      --account-hub-select-margin: 3px;
      grid-template-rows: none;
    }

    &:not(.narrow),
    .stacked & {
      grid-column: span 2;
    }

    &.full:not(.stacked &) {
      grid-column: span 4;
    }

    & .toggle-group {
      grid-row: 2;

      .stacked & {
        grid-row: span 2;
      }
    }

    &.expanded:not(.stacked &) {
      grid-column: span 3;
    }

    & .input-field {
      inline-size: 100%;
    }
  }

  &:not(.advanced) .advanced-input,
  &:not(.advanced) #simpleConfigurationLdap,
  &.advanced #advancedConfigurationLdap {
    display: none;
  }
